"""Самостоятельные постановки для углублённого курса 10 класса."""
from author_tools import N,H,G,P
from math import sqrt
from fractions import Fraction
import ast

def _rows10b(key,data):
    out=[]
    for i,line in enumerate(data.strip().splitlines(),1):
        d,p,a,s,o=line.split('~');a=a.replace('−','-')
        if a.startswith('['):
            value=ast.literal_eval(a);display={('a10-303',2):'−√3; √3',('a10-305',8):'−√2; √2'}.get((key,i));answer=(value,display) if display else value
        elif a.startswith('√'):answer=(sqrt(float(Fraction(a[1:].strip("()")))),{"√(1/3)":"√3/3","√(2/3)":"√6/3"}.get(a,a))
        elif '/' in a:answer=(float(Fraction(a)),a)
        else:answer=float(a)
        out.append((key+'-'+str(i),p,answer,s,o,d))
    return out

def U(n,title,data,subject=H,ref='15–17'):
    N(bank,10,n,subject,title,ref,_rows10b('a10-'+str(n),data))

